import pandas as pd
x=pd.read_csv('records.csv'); x=x[x.kind=='qualification']; g=x.groupby(['project','prototype_id','test','base_sheet','secondary_sheet','binder_system','additive_package_1','additive_package_2','additive_package_3','process_profile_1','process_profile_2','process_profile_3','surface_treatment','joint_system','conditioning_step']).agg(mean=('value','mean'), n=('value','size'), labs=('measured_by',lambda z:','.join(sorted(set(z)))))
g=g.reset_index(); print(g[g.project=='QP-3617'].pivot_table(index=['prototype_id','base_sheet','secondary_sheet','binder_system','additive_package_1','additive_package_2','additive_package_3','process_profile_1','process_profile_2','process_profile_3','surface_treatment','joint_system','conditioning_step'],columns='test',values='mean').tail(25).to_string())